CREATE TABLE categories(id serial primary key,slug text not null unique,name text not null,icon text not null,blurb text not null default '',sort_order integer not null default 0);
CREATE TABLE products(id serial primary key,slug text not null unique,name text not null,name_en text not null default '',price integer not null,old_price integer,category_id integer not null,short_desc text not null default '',description text not null default '',features jsonb not null default '[]',variants jsonb not null default '[]',images jsonb not null default '[]',stock integer not null default 1,prep_time text not null default '',material text not null default '',featured boolean not null default false);
CREATE TABLE users(id serial primary key,email text not null unique,phone text,name text not null,password_hash text not null,role text not null default 'customer',failed_login_count integer not null default 0,locked_until timestamp,last_login_at timestamp,last_login_ip_hash text,created_at timestamp not null default now(),updated_at timestamp not null default now());
CREATE TABLE sessions(id serial primary key,user_id integer not null,token_hash text not null unique,expires_at timestamp not null,ip_hash text,user_agent text,created_at timestamp not null default now());
CREATE TABLE addresses(id serial primary key,user_id integer not null,full_name text not null,phone text not null,province text not null,city text not null,line text not null,postal_code text not null default '',is_default boolean not null default true,created_at timestamp not null default now());
CREATE TABLE orders(id serial primary key,public_id text not null unique,user_id integer,status text not null default 'pending',total_toman integer not null,customer_name text not null,customer_email text not null,customer_phone text not null,province text not null,city text not null,address_line text not null,postal_code text not null default '',note text not null default '',created_at timestamp not null default now(),paid_at timestamp);
CREATE TABLE order_items(id serial primary key,order_id integer not null,product_id integer not null,slug text not null,name text not null,unit_price integer not null,qty integer not null,image text not null default '');
CREATE TABLE payments(id serial primary key,order_id integer not null,provider text not null default 'zarinpal',authority text not null unique,status text not null default 'pending',amount_toman integer not null,amount_rial integer not null,ref_id text,card_pan text,created_at timestamp not null default now(),verified_at timestamp);
CREATE TABLE subscribers(id serial primary key,email text not null unique,created_at timestamp not null default now());
CREATE TABLE messages(id serial primary key,name text not null,contact text not null default '',body text not null,ip_hash text,created_at timestamp not null default now());
